def write_files():
    for rel, content in FILES.items():
        p = os.path.join(ROOT, rel)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        old = open(p, encoding='utf-8').read() if os.path.exists(p) else None
        if old == content:
            print('skip ', rel)
            continue
        open(p, 'w', encoding='utf-8').write(content)
        print('write', rel)


def apply_patches():
    for item in PATCHES:
        rel = item['file']
        p = os.path.join(ROOT, rel)
        if not os.path.exists(p):
            if item['must']:
                raise SystemExit(f'找不到文件：{rel}')
            continue
        s = open(p, encoding='utf-8').read()
        orig = s
        for pair in item['pairs']:
            old, new = pair[0], pair[1]
            skip_if = pair[2] if len(pair) > 2 else None
            replace_all = len(pair) > 3 and pair[3] == 'all'
            if skip_if and skip_if in s:
                continue
            if not replace_all and new in s:
                continue
            if replace_all:
                if old in s:
                    s = s.replace(old, new)
                continue
            if old not in s:
                if item['must']:
                    raise SystemExit(f'[{rel}] 找不到锚点：{old[:60]!r}\n（上游可能改动了这段代码，需要人工确认）')
                continue
            s = s.replace(old, new, 1)
        req = item.get('require')
        if req and req not in s:
            raise SystemExit(f'[{rel}] 打完补丁后仍缺少 {req!r}，需要人工确认')
        if s != orig:
            open(p, 'w', encoding='utf-8').write(s)
            print('patch', rel)
        else:
            print('skip ', rel)


def q(s):
    """转成 TS 单引号字符串。换行必须转义，长文案是多段的。"""
    return (
        "'"
        + s.replace('\\', '\\\\').replace("'", "\\'").replace('\n', '\\n').replace('\r', '')
        + "'"
    )


def block(d, indent='    '):
    out = []
    for k, v in d.items():
        key = k if re.match(r'^[A-Za-z_]\w*$', k) else q(k)
        if isinstance(v, dict):
            out.append(f"{indent}{key}: {{\n{block(v, indent + '  ')}{indent}}},\n")
        else:
            out.append(f"{indent}{key}: {q(v)},\n")
    return ''.join(out)


def section_body(s, name):
    """取出顶层某段（player / runtime / rooms）的正文，用来判断某个键在不在这一段里"""
    anchor = f"\n  {name}: {{\n"
    i = s.find(anchor)
    if i < 0:
        return None, -1
    start = i + len(anchor)
    end = s.find("\n  },\n", start)
    return s[start:end if end > 0 else len(s)], start


def insert_missing(s, name, d):
    """把这一段里缺的键补进去（已有的不动），返回新内容和补了几个"""
    body, start = section_body(s, name)
    if body is None:
        return s, 0
    add = ""
    n = 0
    for k, v in d.items():
        if re.search(r"\n\s{4}" + re.escape(k) + r":", "\n" + body):
            continue
        n += 1
        if isinstance(v, dict):
            add += f"    {k}: {{\n{block(v, '      ')}    }},\n"
        else:
            add += f"    {k}: {q(v)},\n"
    if not add:
        return s, 0
    return s[:start] + add + s[start:], n


def apply_i18n():
    for lang, d in I18N.items():
        p = os.path.join(ROOT, 'src/locales', lang + '.ts')
        if not os.path.exists(p):
            print('skip  locales/' + lang)
            continue
        s = open(p, encoding='utf-8').read()
        orig = s
        if '\n  player: {\n' not in s or '\n  runtime: {\n' not in s:
            raise SystemExit(f'locales/{lang}.ts 结构不符合预期，需要人工确认')

        # rooms 是新增的一整段；player / runtime 按键补齐，不整段覆盖（上游可能改过里面的内容）
        if '\n  rooms: {\n' not in s:
            s = s.replace('\n  player: {\n',
                          '\n  /* ---------------- 联机房间 ---------------- */\n  rooms: {\n' + block(d['rooms']) + '  },\n\n  player: {\n', 1)
        else:
            s, _ = insert_missing(s, 'rooms', d['rooms'])
        added = 0
        for name, section in d.items():
            if name == 'rooms':
                continue
            s, n = insert_missing(s, name, section)
            added += n

        if s != orig:
            open(p, 'w', encoding='utf-8').write(s)
            print(f'i18n  {lang}（补了 {added} 个键）')
        else:
            print('skip  locales/' + lang)


def run_spectator_patches():
    """观众席 / 直播那三个补丁。

    这个脚本的 FILES 会整份覆盖 netplay.js、emulatorjs.ts、netplay.ts，
    而观众功能就加在这三个文件里 —— 不在这里补一遍的话，
    每次重新应用联机功能都会把直播悄悄弄没。三个补丁本身都是幂等的。
    """
    import subprocess
    here = os.path.dirname(os.path.abspath(__file__))
    for name in ('spectator-server.py', 'spectator-client.py', 'spectator-ui.py'):
        script = os.path.join(os.path.dirname(here), 'patches', name)
        if not os.path.exists(script):
            print(f'⚠️  找不到 patches/{name}，观众席这部分没打上')
            continue
        print(f'\n── patches/{name} ──')
        subprocess.run([sys.executable, script, ROOT], check=True)


if __name__ == '__main__':
    if not os.path.isdir(os.path.join(ROOT, 'src/emulator')):
        raise SystemExit(f'{ROOT} 看起来不是 8bitgo 项目根目录')
    write_files()
    apply_patches()
    apply_i18n()
    run_spectator_patches()
    print('\n完成。接着跑：npx tsc -b   （应无输出）')
